argv:
$ErrorActionPreference='Stop'
$dir='E:\PC-Control\TunnelChrome-20261009'
$asset='tunnel-client-v0.0.16-windows-amd64.zip'
$zip=Join-Path $dir $asset
$checks=Join-Path $dir 'SHA256SUMS.txt'
if(!(Test-Path $checks -PathType Leaf)){throw 'missing_verified_manifest'}
if(Test-Path $zip){throw 'full_zip_already_exists'}
$line=@(Get-Content -LiteralPath $checks|Where-Object {$_ -like ('*'+$asset)})|Select-Object -First 1
if(!$line){throw 'sha_not_found'}
$expected=($line.Trim() -split '\s+')[0].ToLowerInvariant()
if($expected -notmatch '^[a-f0-9]{64}$'){throw 'invalid_sha'}
$base='https://github.com/openai/tunnel-client/releases/download/v0.0.16/'
Invoke-WebRequest -Uri ($base+$asset) -OutFile $zip -UseBasicParsing -TimeoutSec 50
$actual=(Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash.ToLowerInvariant()
if($actual -ne $expected){throw 'archive_sha_mismatch'}
$dst=Join-Path $dir 'full'
Expand-Archive -LiteralPath $zip -DestinationPath $dst
$bin=@(Get-ChildItem -LiteralPath $dst -Filter 'tunnel-client.exe' -Recurse -File|Select-Object -First 1)
if($bin.Count -ne 1){$names=@(Get-ChildItem -LiteralPath $dst -Filter '*.exe' -Recurse -File|Select-Object -ExpandProperty Name);throw ('full_binary_not_found: '+($names -join ','))}
[ordered]@{ready=$true;shaVerified=$true;binary=$bin[0].FullName;bytes=(Get-Item $zip).Length}|ConvertTo-Json -Compress
